### Task 2: The backfill script

**Files:**
- Create: `scripts/backfill-cutouts.ts`
- Modify: `package.json`

**Interfaces:**
- Consumes: `needsWebpBackfill`, `webpPathFor` from Task 1.
- Environment: `NEXT_PUBLIC_SUPABASE_URL`, `SUPABASE_SERVICE_ROLE_KEY`.

- [ ] **Step 1: Add the tooling**

```bash
npm install --save-dev sharp tsx
```

Add to `package.json` scripts:

```json
    "backfill:cutouts": "tsx scripts/backfill-cutouts.ts"
```

- [ ] **Step 2: Write the script**

```ts
/**
 * One-off: re-encode existing PNG cutouts as WebP.
 *
 * New captures already store WebP (lib/images/encode.ts). This closes the gap
 * for everything uploaded before that, where the displayed image — the cutout —
 * is an uncompressed PNG larger than the JPEG original it came from.
 *
 * MAINTENANCE TOOLING, NOT APP CODE. It is the only place a service-role key is
 * used; the app itself relies entirely on RLS. Run by hand:
 *
 *   npm run backfill:cutouts            # dry run, changes nothing
 *   npm run backfill:cutouts -- --apply
 */
import { createClient } from "@supabase/supabase-js";
import sharp from "sharp";
import { needsWebpBackfill, webpPathFor } from "../lib/images/paths";

const APPLY = process.argv.includes("--apply");
const BUCKET = "wardrobe";

const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!url || !key) {
  console.error("Set NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY.");
  process.exit(1);
}

const supabase = createClient(url, key, { auth: { persistSession: false } });

async function main() {
  const { data: items, error } = await supabase.from("items").select("id, cutout_url");
  if (error) throw error;

  const todo = (items ?? []).filter((i) => needsWebpBackfill(i.cutout_url));
  console.log(`${todo.length} of ${items?.length ?? 0} cutouts to migrate${APPLY ? "" : " (dry run)"}`);

  let migrated = 0;
  let savedBytes = 0;

  for (const item of todo) {
    const pngPath = item.cutout_url as string;
    const webpPath = webpPathFor(pngPath);

    const { data: blob, error: dlErr } = await supabase.storage.from(BUCKET).download(pngPath);
    if (dlErr || !blob) {
      console.warn(`skip ${item.id}: ${dlErr?.message ?? "no body"}`);
      continue;
    }

    const png = Buffer.from(await blob.arrayBuffer());
    // alphaQuality keeps the cutout edge clean; without it the matte can band.
    const webp = await sharp(png).webp({ quality: 85, alphaQuality: 100 }).toBuffer();

    if (webp.length >= png.length) {
      console.log(`keep  ${item.id}: webp not smaller (${png.length} → ${webp.length})`);
      continue;
    }

    if (!APPLY) {
      console.log(`would ${item.id}: ${png.length} → ${webp.length} bytes`);
      savedBytes += png.length - webp.length;
      continue;
    }

    const { error: upErr } = await supabase.storage
      .from(BUCKET)
      .upload(webpPath, webp, { contentType: "image/webp", upsert: true });
    if (upErr) {
      console.warn(`skip ${item.id}: upload failed ${upErr.message}`);
      continue;
    }

    // Point the row at the WebP. The PNG is deliberately left in place so this
    // run is reversible until it has been verified in the app.
    const { error: rowErr } = await supabase
      .from("items")
      .update({ cutout_url: webpPath })
      .eq("id", item.id);
    if (rowErr) {
      console.warn(`skip ${item.id}: row update failed ${rowErr.message}`);
      continue;
    }

    migrated++;
    savedBytes += png.length - webp.length;
    console.log(`ok    ${item.id}: ${png.length} → ${webp.length} bytes`);
  }

  console.log(
    `${APPLY ? "migrated" : "would migrate"} ${APPLY ? migrated : todo.length} cutouts, ` +
      `saving ~${(savedBytes / 1024 / 1024).toFixed(1)} MB`,
  );
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
```

- [ ] **Step 3: Dry-run against local**

```bash
