### Task 1: The ledger

**Files:**
- Create: `supabase/migrations/20260722110000_generation_events.sql`

- [ ] **Step 1: Write the migration**

```sql
-- Every real AI generation, recorded. The daily `outfits` rows cannot serve as
-- the counter because a regenerate REPLACES them — the act of regenerating
-- erases its own evidence. This ledger is append-only.
create table if not exists public.generation_events (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles(id) on delete cascade,
  occasion     text not null,
  generated_on date not null,          -- the user's LOCAL date, as with outfits
  is_regenerate boolean not null,      -- false = the day's free drop for this occasion
  created_at   timestamptz default now()
);

create index if not exists generation_events_daily
  on public.generation_events (user_id, generated_on);

alter table public.generation_events enable row level security;

create policy generation_events_own on public.generation_events
  for all using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);

-- Plan is per-user and defaults to free. Kept as text rather than an enum so a
-- new tier is a product decision, not a migration.
alter table public.profiles add column if not exists plan text not null default 'free';
```

