```ts
/**
 * Texture carries warmth that `material` cannot: a chunky merino knit and a
 * fine merino knit are the same material and a season apart in practice. The
 * tagger records it (lib/ai/tagging-schema.ts); until now nothing read it.
 *
 * This is a PREFERENCE. It shifts ranking with the temperature and can never
 * eliminate a candidate — the same model as outerwear, the colour lean and
 * season, each of which was a hard filter that silently emptied a wardrobe.
 */
const WARMTH: Record<string, number> = {
  "Fine knit": 0.25,
  Flat: 0.4,
  Twill: 0.45,
  Herringbone: 0.55,
  Waffle: 0.6,
  Ribbed: 0.6,
  Brushed: 0.7,
  Corduroy: 0.7,
  "Cable knit": 0.8,
  Quilted: 0.85,
  Pile: 0.85,
  "Chunky knit": 0.9,
  "Fleece-back": 0.9,
};

/** 0 = coolest, 1 = warmest, 0.5 = no opinion (untagged or unknown). */
export function textureWarmth(texture: string | null): number {
  if (!texture) return 0.5;
  return WARMTH[texture] ?? 0.5;
}

/**
 * How well a combo's warmth suits the temperature.
 *
 * `want` maps 25°+ → 0 (want the lightest) and 0° → 1 (want the warmest), so in
 * mild weather it sits near 0.5 and the term stops discriminating on its own —
 * which is correct: at 18° a ribbed knit and a flat shirt are both fine.
 */
export function warmthFit(items: { texture?: string | null }[], tempC: number): number {
  if (!items.length) return 0.5;
  const want = Math.min(1, Math.max(0, (25 - tempC) / 25));
  const have = items.reduce((s, i) => s + textureWarmth(i.texture ?? null), 0) / items.length;
  return 1 - Math.abs(want - have);
}
```

