import { z } from "zod";

/**
 * Defaults live here, not in the database, so a row written before a preference
 * existed reads correctly instead of behaving as `undefined`.
 *
 * `rainGuard` defaults ON because the protective behaviour already shipped and
 * silently changing it would be a regression. `autoLogWorn` defaults OFF
 * because it writes history on the user's behalf, and opting someone into
 * data-writing without asking is not ours to do.
 */
export const PreferencesSchema = z.object({
  rainGuard: z.boolean().default(true),
  autoLogWorn: z.boolean().default(false),
});
export type Preferences = z.infer<typeof PreferencesSchema>;

export function readPreferences(raw: unknown): Preferences {
  const parsed = PreferencesSchema.safeParse(raw ?? {});
  return parsed.success ? parsed.data : PreferencesSchema.parse({});
}
