  const s = itemWearStats([], 100, "2026-07-24");
  expect(s.wears).toBe(0);
  expect(s.costPerWear).toBeNull();
});

test("last worn reads in human time, counting from the most recent wear", () => {
  expect(itemWearStats([{ worn_on: "2026-07-24" }], null, "2026-07-24").lastWorn).toBe("Today");
  expect(itemWearStats([{ worn_on: "2026-07-23" }], null, "2026-07-24").lastWorn).toBe("Yesterday");
  expect(itemWearStats([{ worn_on: "2026-07-14" }], null, "2026-07-24").lastWorn).toBe("10 days ago");
});

test("the most recent wear wins, not the first in the list", () => {
  const s = itemWearStats(
    [{ worn_on: "2026-07-01" }, { worn_on: "2026-07-23" }, { worn_on: "2026-06-02" }],
    null,
    "2026-07-24",
  );
  expect(s.lastWorn).toBe("Yesterday");
});

test("never worn says so plainly", () => {
  expect(itemWearStats([], null, "2026-07-24").lastWorn).toBe("Never");
});
```

- [ ] **Step 2: Run it — expect FAIL**

- [ ] **Step 3: Implement**

```ts
const GBP = new Intl.NumberFormat("en-GB", { style: "currency", currency: "GBP" });

function daysBetween(from: string, to: string): number {
  const a = Date.UTC(+from.slice(0, 4), +from.slice(5, 7) - 1, +from.slice(8, 10));
  const b = Date.UTC(+to.slice(0, 4), +to.slice(5, 7) - 1, +to.slice(8, 10));
  return Math.round((b - a) / 86_400_000);
}

/**
 * The three tiles at the top of item detail.
 *
 * Cost-per-wear is null rather than 0 or "—" when there is no price or no
 * wears: dividing by zero wears would print £Infinity, and showing £0.00 for an
 * unpriced item states something false. The UI hides the tile instead.
 */
export function itemWearStats(
  logs: { worn_on: string }[],
  price: number | null,
  today: string,
): { wears: number; costPerWear: string | null; lastWorn: string } {
  const wears = logs.length;
  const costPerWear = price != null && wears > 0 ? GBP.format(price / wears) : null;

  if (!wears) return { wears, costPerWear, lastWorn: "Never" };

  const latest = logs.reduce((a, b) => (a.worn_on > b.worn_on ? a : b)).worn_on;
  const d = daysBetween(latest, today);
  const lastWorn = d <= 0 ? "Today" : d === 1 ? "Yesterday" : `${d} days ago`;
  return { wears, costPerWear, lastWorn };
}
```

- [ ] **Step 4: Run it — expect PASS (6 tests)**
- [ ] **Step 5: Commit** — `git commit -m "feat(closet): per-item wear statistics"`

