"use server";

import { revalidatePath } from "next/cache";
import { createClient } from "@/lib/supabase/server";
import { localDateKey } from "@/lib/outfits/local-date";

/**
 * Log or unlog "I wore this today".
 *
 * Two things happen on a log, and the second is the important one: the outfit's
 * `generated_on` is nulled, which GRADUATES it out of the daily drop. Both
 * loadDailyLooks and saveDailyLooks filter on `generated_on`, so a worn look is
 * no longer offered as a suggestion AND is no longer deleted by a Regenerate.
 * Without this, wearing a look and then regenerating the same day raised a
 * foreign-key violation and the regeneration failed.
 *
 * Unlogging deliberately does NOT restore `generated_on`. The day's suggestions
 * have moved on; putting a look back into a set that may since have been
 * regenerated would either duplicate an index or resurrect a stale look.
 */
export async function toggleWear(outfitId: string): Promise<{ worn: boolean }> {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) throw new Error("Not signed in");

  const today = localDateKey(new Date());

  // RLS scopes every statement below to the owner; a foreign id matches 0 rows.
  const { data: existing } = await supabase
    .from("wear_logs")
    .select("id")
    .eq("outfit_id", outfitId)
    .eq("worn_on", today)
    .maybeSingle();

  if (existing) {
    const { error } = await supabase.from("wear_logs").delete().eq("id", existing.id);
    if (error) throw new Error(error.message);
    revalidatePath(`/outfits/${outfitId}`);
    revalidatePath("/calendar");
    return { worn: false };
  }

  const { data: outfit } = await supabase
    .from("outfits")
    .select("occasion")
    .eq("id", outfitId)
    .single();

  const { error } = await supabase.from("wear_logs").insert({
    user_id: user.id,
    outfit_id: outfitId,
    worn_on: today,
    occasion: outfit?.occasion ?? null,
  });
  if (error) throw new Error(error.message);

  // Graduate it out of the daily drop — see the comment above.
  await supabase.from("outfits").update({ generated_on: null }).eq("id", outfitId);

  revalidatePath(`/outfits/${outfitId}`);
  revalidatePath("/calendar");
  revalidatePath("/generate");
  return { worn: true };
}

export async function toggleFavorite(outfitId: string): Promise<{ favorite: boolean }> {
  const supabase = await createClient();
  const { data: row } = await supabase
    .from("outfits")
    .select("is_favorite")
    .eq("id", outfitId)
    .single();

  const next = !row?.is_favorite;
  const { error } = await supabase
    .from("outfits")
    .update({ is_favorite: next })
    .eq("id", outfitId);
  if (error) throw new Error(error.message);

  revalidatePath(`/outfits/${outfitId}`);
  return { favorite: next };
}
```

