609	```ts
610	function materialExcluded(material: string | null, excludeMaterials: string[]): boolean {
611	  if (!material) return false;
612	  const m = material.toLowerCase();
613	  // Substring, not equality: the tagger writes free text, so "merino wool" and
614	  // "suede leather" are real values that an exact match silently let through.
615	  return excludeMaterials.some((x) => m.includes(x));
616	}
617	
618	function isEligible(i: CandidateItem, a: CandidateArgs, excludeMaterials: string[]): boolean {
619	  const [lo, hi] = a.band;
620	  if (i.category === "Fragrance") return false; // D11: fragrances are never slotted
621	  if (a.excludeItemIds.includes(i.id)) return false;
622	  if (materialExcluded(i.material, excludeMaterials)) return false;
623	  // Season is deliberately NOT filtered here — see ./season.ts. It orders the
624	  // lists below and weights the score instead. Filtering ran against every
625	  // required slot, so one narrowly-tagged category zeroed the whole result.
626	  const f = i.formality ?? 3;
627	  return f >= lo - floorTolerance(i.category) && f <= hi + 0.5;
628	}
629	
630	function bySeasonFirst(list: CandidateItem[], season: string | undefined): CandidateItem[] {
631	  return [...list].sort(
632	    (x, y) => Number(inSeason(y.seasons, season)) - Number(inSeason(x.seasons, season)),
633	  );
634	}
635	
636	function isRequired(c: string): c is RequiredCategory {
637	  return (REQUIRED_CATEGORIES as readonly string[]).includes(c);
638	}
639	
640	/**
641	 * The eligible items of every category, in-season first.
642	 *
643	 * Two soft rules live here, and `eligibility`, `missingCategory` and
644	 * `buildCandidates` all read from this one function so they can never disagree
645	 * about what the closet can do:
646	 *
647	 * 1. Season ORDERS, never excludes. The CAP in `buildCandidates` truncates the
648	 *    combo list, so in-season pieces must come first or a large off-season
649	 *    closet could push the good combos past the cap.
650	 * 2. Material RELIEF: a weather exclusion may narrow a REQUIRED slot but must
651	 *    never empty it. A closet whose only shoes are suede should get its suede
652	 *    shoes on a wet day, not an empty screen blaming "Shoes". Relief is scoped
653	 *    to weather exclusions — a formality gap is a real wardrobe gap and is still
654	 *    reported.
655	 */
656	export function eligibleByCategory(
657	  items: CandidateItem[],
658	  a: CandidateArgs,
659	): Record<string, CandidateItem[]> {
660	  const { excludeMaterials } = weatherRules(a.weather);
661	  const cats = new Set<string>(items.map((i) => i.category));
662	  for (const c of REQUIRED_CATEGORIES) cats.add(c);
663	  cats.add("Outerwear");
664	
665	  const out: Record<string, CandidateItem[]> = {};
666	  for (const c of cats) {
667	    const inCat = items.filter((i) => i.category === c);
668	    let list = inCat.filter((i) => isEligible(i, a, excludeMaterials));
669	    if (!list.length && isRequired(c)) list = inCat.filter((i) => isEligible(i, a, []));
670	    out[c] = bySeasonFirst(list, a.season);
671	  }
672	  return out;
673	}
674	
675	/** Per-category counts of what survived filtering — lets an empty result explain itself. */
676	export function eligibility(items: CandidateItem[], a: CandidateArgs): Record<string, number> {
677	  const by = eligibleByCategory(items, a);
678	  const counts: Record<string, number> = {};
679	  for (const c of Object.keys(by)) counts[c] = by[c].length;
680	  return counts;
681	}
682	
683	/**
684	 * Which required slot came up empty, or null if the closet can dress this band.
685	 * The screen uses this to say WHICH gap blocked the outfit instead of a generic
686	 * "add more pieces". Outerwear is never a reason — it does not block (see below).
687	 */
688	export function missingCategory(items: CandidateItem[], a: CandidateArgs): RequiredCategory | null {
689	  const counts = eligibility(items, a);
690	  return REQUIRED_CATEGORIES.find((c) => counts[c] === 0) ?? null;
691	}
692	
693	export function buildCandidates(items: CandidateItem[], a: CandidateArgs): CandidateItem[][] {
694	  const { needsOuterwear } = weatherRules(a.weather);
695	
696	  const by = eligibleByCategory(items, a);
697	  const tops = by.Tops ?? [];
698	  const bottoms = by.Bottoms ?? [];
699	  const shoes = by.Shoes ?? [];
700	  const outer = by.Outerwear ?? [];
701	  const accessories = by.Accessories ?? [];
702	
703	  const combos: CandidateItem[][] = [];
704	  for (const t of tops)
705	    for (const b of bottoms)
706	      for (const s of shoes) {
707	        // Outerwear is a PREFERENCE, not a requirement: layer it in when the cold
708	        // calls for it and the closet has one, but never refuse to dress someone
709	        // who owns no coat — that silently killed every outfit below 15°.
710	        // The weather strip's "Later" advice is what tells them to take a layer.
711	        const base = needsOuterwear && outer.length ? [t, b, s, outer[0]] : [t, b, s];
712	        combos.push(base); // required base (± outerwear), no accessory
713	        if (a.maxAccessories > 0 && accessories.length) {
714	          combos.push([...base, accessories[0]]); // optional, capped accent
715	        }
716	      }
717	
718	  // Colour is deliberately NOT filtered here. The Refine palette is a lean, and
719	  // leans are expressed by ranking (`scoreCombo`'s lean term), not by exclusion —
720	  // the same soft-preference model as outerwear, season and materials above.
721	  return combos.slice(0, CAP);
722	}
723	```
