// CATEGORIES/SEASONS from this schema, so importing back would be a cycle.
// vocab.ts re-exports these two as the shared source.
export const MATERIALS = [
  "Cotton", "Wool", "Merino wool", "Cashmere", "Linen", "Silk", "Denim",
  "Leather", "Suede", "Canvas", "Corduroy", "Tweed", "Fleece", "Down",
  "Polyester", "Nylon", "Viscose", "Lyocell", "Stainless steel", "Gold",
  "Silver", "Rubber", "Other",
] as const;

