export const PRO: Entitlements = {
  tier: "pro",
  generationsPerDay: null,
  savedOutfits: null,
  analytics: true,
  gapAnalysis: true,
  packingMode: true,
};

// The two PURE functions live here, not in entitlements.ts, so the tests can
// import them without dragging in `server-only` (which does not resolve under
// jsdom). entitlements.ts re-exports them for app code.

/** Unknown input resolves to free: capabilities fail CLOSED. */
export function entitlementsFor(tier: unknown): Entitlements {
  return tier === "pro" ? PRO : FREE;
}

export function checkGenerations(
  e: Entitlements,
  usedToday: number,
): { allowed: boolean; remaining: number | null; reason?: string } {
  if (e.generationsPerDay == null) return { allowed: true, remaining: null };
  const remaining = Math.max(0, e.generationsPerDay - usedToday);
  return remaining > 0
    ? { allowed: true, remaining }
    : {
        allowed: false,
        remaining: 0,
        reason: "You've used today's looks. Pro gives you unlimited.",
      };
}
```

